per_case_results.actual_sql:
SELECT (COUNT(CASE WHEN EXTRACT(YEAR FROM "Birthday") > 1930 AND "SEX" = 'F' THEN 1 END) * 100.0 / COUNT(CASE WHEN "SEX" = 'F' THEN 1 END)) AS percentage
FROM "Patient"
WHERE "SEX" = 'F';

SELECT CASE WHEN ("UA" > 8.0 AND "SEX" = 'M') OR ("UA" > 6.5 AND "SEX" = 'F') THEN 'Yes' ELSE 'No' END AS uric_acid_normal
FROM "Patient"
WHERE "ID" = 57266;
